for(const id of['cohort','education','filter','search','dimension','category'])get('r79-'+id).addEventListener(id==='search'?'input':'change',()=>{page=0;render();});get('r79-prev').onclick=()=>{page--;render();};get('r79-next').onclick=()=>{page++;render();};
